using namespace std;

// Recursive Fibonacci function with error handling
pair<int, int> fibonacci(int prev1, int prev2, int count, int& errorCount) {
    if (count <= 0) {
        errorCount++;  // Increment error count for invalid count
        return make_pair(prev1, prev2); // Return original values on unterminated recursion
    } else if (count == 1) {
        return make_pair(prev1, prev2); // Base case: return initial values
    } else {
        int next = prev1 + prev2;
        return fibonacci(prev2, next, count - 1, errorCount); // Recursive step
    }
}

