public static decimal CalculateTotalCostWithConstraint(decimal carPrice, decimal clothesPrice, decimal bookPrice)
{
    decimal combinedItemCost = clothesPrice + bookPrice;

    while (carPrice < 2 * combinedItemCost)
    {
        carPrice += 100; // Adjust increment as needed for realistic scenarios
    }

    decimal totalCost = carPrice + clothesPrice + bookPrice;
    return totalCost;
